const input = $input.first().json;

// Get Gemini response text
const text = input.content?.parts?.[0]?.text || "";

let report;

try {
  // Remove markdown code blocks if Gemini returns them
  const cleanText = text
    .replace(/```json/g, "")
    .replace(/```/g, "")
    .trim();

  report = JSON.parse(cleanText);
} catch (error) {
  // If Gemini does not return valid JSON
  report = {
    raw_report: text
  };
}

return [
  {
    json: {
      product_name:
        report.productName ||
        report.product_name ||
        report.product?.name ||
        "Not Available",

      brand:
        report.brand ||
        report.product?.brand ||
        "Not Available",

      compliance_status:
        report.complianceStatus ||
        report.compliance_status ||
        "Under Review",

      report: report
    }
  }
];;
